default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Cryptography' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('ForceKeyProtection', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_force_key_protection)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Cryptography [ForceKeyProtection]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_2 }}
  {{ if .Vars.win11cis_rule_2_3_14_1 }}
registry:
  HKLM\SOFTWARE\Policies\Microsoft\Cryptography\ForceKeyProtection:
    title: "2.3.14.1 | Ensure 'System cryptography: Force strong key protection for user keys stored on the computer' is set to 'User is prompted when the key is first used' or higher | ForceKeyProtection"
    exists: true
    value: {{ .Vars.win11cis_force_key_protection }}
    type: REG_DWORD
    meta:
      workstation: 2
      CIS_ID:
        - 2.3.14.1
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Cryptography')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Cryptography' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Cryptography' -Name 'ForceKeyProtection' -Value $ODV_force_key_protection -PropertyType DWord -Force | Out-Null
exit 0
